<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Clerk'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$id=filter_var($_POST['vehicle_id']??null,FILTER_VALIDATE_INT);$registration=strtoupper(trim((string)($_POST['registration']??'')));$model=trim((string)($_POST['make_model']??''));$capacity=filter_var($_POST['seat_capacity']??null,FILTER_VALIDATE_INT);$driverRaw=trim((string)($_POST['driver_user_id']??''));$driver=$driverRaw===''?null:filter_var($driverRaw,FILTER_VALIDATE_INT);$roadworthy=trim((string)($_POST['roadworthy_until']??''));$insurance=trim((string)($_POST['insurance_until']??''));$status=(string)($_POST['status']??'Active');
$dateOk=static function(string $v):bool{if($v==='')return true;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);$e=DateTimeImmutable::getLastErrors();return $d!==false&&$d->format('Y-m-d')===$v&&($e===false||(!$e['warning_count']&&!$e['error_count']));};
if($id===false||$driver===false||$registration===''||strlen($registration)>24||$model===''||strlen($model)>100||!$capacity||$capacity>200||!in_array($status,['Active','Maintenance','Retired'],true)||!$dateOk($roadworthy)||!$dateOk($insurance)){$_SESSION['error']='Enter a valid registration, vehicle, seat capacity, status and inspection dates.';header('Location: ../?page=transport');exit;}
$pdo=db();try{$pdo->beginTransaction();if($driver){$q=$pdo->prepare("SELECT id FROM users WHERE id=:id AND active=1 AND role IN ('Administrator','Head','Teacher','Clerk') FOR UPDATE");$q->execute(['id'=>$driver]);if(!$q->fetch())throw new DomainException('Choose an active staff member as driver.');}if($id){$q=$pdo->prepare('SELECT id,status FROM transport_vehicles WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$old=$q->fetch();if(!$old)throw new DomainException('Vehicle not found.');$q=$pdo->prepare("SELECT COUNT(*) FROM transport_assignments a JOIN transport_routes r ON r.id=a.route_id WHERE r.vehicle_id=:vehicle AND a.status='Active' AND (a.ends_on IS NULL OR a.ends_on>=CURDATE())");$q->execute(['vehicle'=>$id]);$passengers=(int)$q->fetchColumn();if($capacity<$passengers)throw new DomainException('Seat capacity cannot be lower than the current and scheduled route allocations.');if($status!=='Active'&&$passengers>0)throw new DomainException('Move or end all current route allocations before setting this vehicle to maintenance or retired.');$q=$pdo->prepare('UPDATE transport_vehicles SET registration=:registration,make_model=:model,seat_capacity=:capacity,driver_user_id=:driver,roadworthy_until=:roadworthy,insurance_until=:insurance,status=:status WHERE id=:id');$q->execute(['registration'=>$registration,'model'=>$model,'capacity'=>$capacity,'driver'=>$driver?:null,'roadworthy'=>$roadworthy?:null,'insurance'=>$insurance?:null,'status'=>$status,'id'=>$id]);audit_log('transport.vehicle_updated','transport_vehicles',(int)$id,['status'=>$status,'seat_capacity'=>$capacity]);}else{$q=$pdo->prepare('INSERT INTO transport_vehicles(registration,make_model,seat_capacity,driver_user_id,roadworthy_until,insurance_until,status,created_by) VALUES(:registration,:model,:capacity,:driver,:roadworthy,:insurance,:status,:user)');$q->execute(['registration'=>$registration,'model'=>$model,'capacity'=>$capacity,'driver'=>$driver?:null,'roadworthy'=>$roadworthy?:null,'insurance'=>$insurance?:null,'status'=>$status,'user'=>$user['id']]);$id=(int)$pdo->lastInsertId();audit_log('transport.vehicle_created','transport_vehicles',$id,['registration'=>$registration,'seat_capacity'=>$capacity]);}$pdo->commit();$_SESSION['notice']='Vehicle record saved.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Transport vehicle save failed: '.$e->getMessage());$_SESSION['error']=$e instanceof DomainException?$e->getMessage():($e instanceof PDOException&&$e->getCode()==='23000'?'That registration is already in use.':'Could not save the vehicle.');}header('Location: ../?page=transport');exit;
